function highlight(){document.querySelectorAll('.measure.active').forEach(e=>e.classList.remove('active'));document.querySelectorAll('.notecell.current').forEach(e=>e.classList.remove('current'));if(currentIndex==null)return;const n=score.notes.find(n=>n.id===currentIndex);if(n){document.querySelector(`[data-measure="${n.measure}"]`)?.classList.add('active');document.querySelector(`[data-note="${n.id}"]`)?.classList.add('current');}}
